('IQ', 'Sequence', 'Sequence: B2, E6, I12, N20, ?', NULL, '["T30","S30","T28","U30"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Letter sequence skips +3, +4, +5, +6: B(2)->E(5)->I(9)->N(14)->T(20). Number sequence is n*(n+1): 1*2=2, 2*3=6, 3*4=12, 4*5=20, 5*6=30. Next term is T30.', NULL, FALSE),
('IQ', 'Analogy', 'Analogy: ORBIT : PLANET :: MATRIX : ?', NULL, '["ELEMENT","NUMBER","SPACE","GRID"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'A planet is bound by and moves along an orbit; an element is positioned within and bounded by a matrix.', NULL, FALSE),
('IQ', 'Logic', 'Logic: No A are B. All C are B. Which statement must be true?', NULL, '["No A are C","Some A are C","All B are C","Some C are A"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Since all C are contained in B, and no A intersects B, it is logically impossible for any A to be C (No A are C).', NULL, FALSE),
('IQ', 'Math', 'Number Pattern: 4 (18) 5 | 6 (28) 5 | 7 (?) 4', NULL, '["26","28","30","24"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'The pattern is (First * Third) - 2: (4 * 5) - 2 = 18; (6 * 5) - 2 = 28; therefore (7 * 4) - 2 = 26.', NULL, FALSE),
('IQ', 'Math', 'Odd One Out: 121, 169, 225, 289', NULL, '["225","121","169","289"]'::jsonb, 0, '[1,0,0,0]'::jsonb, '121 (11²), 169 (13²), and 289 (17²) are squares of prime numbers. 225 (15²) is the square of a composite number.', NULL, FALSE),
('IQ', 'Logic', 'Code: If MIND = 13-9-14-4, what word is 20-18-21-5?', NULL, '["TRUE","TREE","TUNE","TIRE"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Letters correspond directly to their alphabetical positions: 20=T, 18=R, 21=U, 5=E -> TRUE.', NULL, FALSE),
('IQ', 'Spatial', 'Direction: Face North, turn 135° clockwise, then 225° counter-clockwise. Final direction?', NULL, '["West","East","South-West","North-West"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Starting North (0°), turn 135° clockwise to Southeast (135°), then 225° counter-clockwise: 135° - 225° = -90° (90° counter-clockwise from North = West).', NULL, TRUE),
('IQ', 'Sequence', 'Sequence: 3, 5, 11, 29, 83, ?', NULL, '["245","249","241","253"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Differences between terms triple each step: +2, +6, +18, +54. Next difference is 54 * 3 = +162; 83 + 162 = 245.', NULL, FALSE),
('IQ', 'Logic', 'Logic: All coders drink coffee. Some artists are coders. Therefore:', NULL, '["Some artists drink coffee","All coffee drinkers are artists","All artists drink coffee","No artists drink coffee"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'All coders drink coffee. Since some artists belong to the group of coders, those specific artists must also drink coffee.', NULL, FALSE),
('IQ', 'Spatial', 'Pattern: Z1A, X4C, V9E, T16G, ?', NULL, '["R25I","S25I","R25H","Q25I"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'First letters step back by 2 (Z, X, V, T, R). Middle numbers are squares (1², 2², 3², 4², 5²=25). Last letters step forward by 2 (A, C, E, G, I). Answer: R25I.', NULL, TRUE),
('IQ', 'Sequence', 'Sequence: 2, 6, 12, 20, 30, ?', NULL, '["42","40","44","36"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Differences increase by +2 each step: +4, +6, +8, +10. Next difference is +12; 30 + 12 = 42 (also n*(n+1): 6*7 = 42).', NULL, FALSE),
('IQ', 'Analogy', 'Analogy: CATALYST : REACTION :: SPARK : ?', NULL, '["IGNITION","FLAME","SMOKE","HEAT"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'A catalyst triggers or accelerates a chemical reaction; a spark triggers an ignition.', NULL, FALSE),
('IQ', 'Math', 'Math Logic: If 3 * 4 = 19 and 5 * 2 = 17, what is 4 * 6?', NULL, '["34","24","30","28"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Formula: (a * b) + (a + b): (3*4)+(3+4)=19; (5*2)+(5+2)=17; (4*6)+(4+6)=24+10=34.', NULL, FALSE),
('IQ', 'Spatial', 'Clock Logic: What is the smaller angle between clock hands at 3:30?', NULL, '["75°","90°","60°","80°"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'At 3:30, minute hand is at 180° (6 o''clock). Hour hand is halfway between 3 and 4: 3.5 * 30° = 105°. Separation angle = 180° - 105° = 75°.', NULL, TRUE),
('IQ', 'Sequence', 'Series: AZ, GT, MN, ?, YB', NULL, '["SH","RI","TH","SG"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Pairs are opposite alphabet letters: A-Z, G-T, M-N, S-H, Y-B. First letters step by +6: A(1)->G(7)->M(13)->S(19)->Y(25). Answer: SH.', NULL, FALSE),
('IQ', 'Logic', 'Logic: If it rains, the ground gets wet. The ground is dry. Therefore:', NULL, '["It did not rain","It rained lightly","It will rain soon","Cannot be determined"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Modus Tollens logic: ''If P then Q; Not Q; Therefore Not P''. Since the ground is dry, it did not rain.', NULL, FALSE),
('IQ', 'Math', 'Number Grid: 8 (20) 4 | 10 (25) 5 | 12 (?) 6', NULL, '["30","28","36","24"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'The formula across rows is Left + (3 * Right) = Center: 8 + (3*4) = 20; 10 + (3*5) = 25; 12 + (3*6) = 30.', NULL, FALSE),
('IQ', 'Math', 'Odd One Out: 27, 64, 125, 144', NULL, '["144","27","64","125"]'::jsonb, 0, '[1,0,0,0]'::jsonb, '27 (3³), 64 (4³), and 125 (5³) are cubes of positive integers. 144 (12²) is a perfect square, not a cube.', NULL, FALSE),
('IQ', 'Sequence', 'Sequence: 1, 1, 2, 3, 5, 8, 13, ?', NULL, '["21","19","24","20"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Fibonacci summation: each term is the sum of the two preceding numbers: 5 + 8 = 13, then 8 + 13 = 21.', NULL, FALSE),
('IQ', 'Logic', 'Code: If FAST = 43 and SLOW = 69, what is STOP?', NULL, '["70","68","72","66"]'::jsonb, 0, '[1,0,0,0]'::jsonb, 'Sum of letter positions: S(19) + T(20) + O(15) + P(16) = 70.', NULL, FALSE),
